    @OptIn(ExperimentalEncodingApi::class)
    private fun decode(b64: String): FloatArray {
        val raw = Base64.decode(b64)
        return FloatArray(raw.size) { idx -> ULAW_TABLE[raw[idx].toInt() and 0xFF] }
    }

    private val cache = mutableMapOf<InstrumentTimbre, ReferenceSample>()

    fun get(timbre: InstrumentTimbre): ReferenceSample = cache.getOrPut(timbre) {
        when (timbre) {
            InstrumentTimbre.WARM_KEYS -> ReferenceSample(69.0, decode(WARM_KEYS_B64))
            InstrumentTimbre.FLUTE -> ReferenceSample(69.0, decode(FLUTE_B64))
            InstrumentTimbre.REED -> ReferenceSample(65.0, decode(REED_B64))
            InstrumentTimbre.BRASS -> ReferenceSample(62.0, decode(BRASS_B64))
            InstrumentTimbre.STRING -> ReferenceSample(69.0, decode(STRING_B64))
        }
    }
